/* =========================================================
   三折頁互動：拖曳 / 點擊 / 鍵盤 / 觸控 / 響應式縮放 / 進場
   openProgress 0 = 完全收合（只見最右側封面）
                1 = 完全展開（還原 PPT 原始版面）
   ========================================================= */

window.mountTrifold1 = function (root) {
  'use strict';
  root.innerHTML = window.__trifold1Assets.style + window.__trifold1Assets.markup;

  var PPT_W = 1491.63;
  var PPT_H = 1152;
  var MAX_DRAG = 520;          // 完整展開所需的水平拖曳距離 (px)
  var GESTURE_LOCK = 8;        // 判定水平手勢的門檻 (px)

  var stage = root.getElementById('stage');
  var wrapper = root.querySelector('.brochure-entry-wrapper');
  var scaler = root.querySelector('.brochure-scaler');
  var section = root.querySelector('.brochure-section');
  var source = root.getElementById('ppt-artwork');

  if (!stage || !source) { return null; }

  /* ---------- 1. 以單一來源複製 PPT 版面到中央與封面面板 ---------- */

  Array.prototype.forEach.call(
    root.querySelectorAll('.panel-artwork'),
    function (holder) {
      if (holder !== source) {
        holder.innerHTML = source.innerHTML;
      }
      holder.style.setProperty('--artwork-offset', holder.dataset.artworkOffset + 'px');
    }
  );

  /* ---------- 2. 展開進度 → 面板角度（與三折頁2完全一致的公式/角度/duration/easing） ---------- */

  var isOpen = false;
  var currentProgress = 0;

  function clamp01(v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }

  function prefersReduced() {
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  }

  function apply(p) {
    var h1 = clamp01(p / 0.6);
    var h2 = clamp01((p - 0.4) / 0.6);
    stage.style.setProperty('--open-progress', p.toFixed(4));
    stage.style.setProperty('--hinge1', h1.toFixed(4));
    stage.style.setProperty('--hinge2', h2.toFixed(4));
    stage.style.setProperty('--center-angle', (-180 * (1 - h1)).toFixed(3) + 'deg');
    stage.style.setProperty('--left-angle', (180 * (1 - h2)).toFixed(3) + 'deg');
    stage.setAttribute('aria-expanded', p > 0.5 ? 'true' : 'false');
  }

  apply(0);

  // completion detection: transitionend on the last hinge (panel-left), same
  // as tri-fold 2's onceTransitionEnd, with the same 850ms fallback
  function onceTransitionEnd(cb) {
    var done = false;
    var el = root.getElementById('panel-left');
    function fin(e) {
      if (done) return;
      if (e && e.propertyName && e.propertyName !== 'transform') return;
      done = true;
      el.removeEventListener('transitionend', fin);
      cb();
    }
    el.addEventListener('transitionend', fin);
    if (prefersReduced()) { setTimeout(fin, 0); } else { setTimeout(fin, 1500); }
  }

  /* ---------- 3/4. 手動拖曳與鍵盤切換已移除 —— 三折頁只由頁面呼叫 open()/close()/reset() 自動播放 ---------- */

  /* ---------- 5. 響應式：只縮放整個舞台 ---------- */

  function resize() {
    // While the user is pinch-zoomed in to read the fold, don't re-fit it to
    // the screen — that would snap their zoom away. Resume once zoom returns to 1.
    if (window.visualViewport && window.visualViewport.scale > 1.01) return;
    var availW = (section.clientWidth || window.innerWidth) - 48;
    var availH = window.innerHeight - 48;
    var scale = Math.min(availW / PPT_W, availH / PPT_H);
    if (!isFinite(scale) || scale <= 0) { scale = 1; }
    scaler.style.setProperty('--stage-scale', scale);
    scaler.style.setProperty('--scaled-w', (PPT_W * scale) + 'px');
    scaler.style.setProperty('--scaled-h', (PPT_H * scale) + 'px');
  }

  resize();
  window.addEventListener('resize', resize);
  window.addEventListener('orientationchange', resize);

  /* ---------- 6. 進場跳動（IntersectionObserver） ---------- */

  if ('IntersectionObserver' in window && wrapper) {
    var armed = true;
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.intersectionRatio >= 0.4 && armed) {
          armed = false;
          wrapper.classList.remove('is-entering');
          void wrapper.offsetWidth;
          wrapper.classList.add('is-entering');
        } else if (entry.intersectionRatio <= 0.1) {
          armed = true;
          wrapper.classList.remove('is-entering');
        }
      });
    }, { threshold: [0, 0.1, 0.4, 0.75] });
    io.observe(wrapper);
  }

  /* ---------- 7. Controller returned to the host page ---------- */
  return {
    open: function (onDone) {
      isOpen = true;
      currentProgress = 1;
      apply(1);
      if (onDone) onceTransitionEnd(onDone);
    },
    close: function (onDone) {
      isOpen = false;
      currentProgress = 0;
      apply(0);
      if (onDone) onceTransitionEnd(onDone);
    },
    reset: function () {
      isOpen = false;
      currentProgress = 0;
      apply(0);
    }
  };
};

